/**
 * Two-brand legacy characterization fixtures.
 *
 * This is repository characterization evidence, not external approval. It pins
 * the legacy `PathRule` allow/deny expectations for two brands across Guest,
 * Researcher, Librarians, Admin, a custom role, and the bootstrap
 * administrator, including multi-role additive behavior and representative
 * bearer shapes. Intentional security fixes live separately in
 * `authorization-security-differences.fixtures.ts` and are excluded from
 * parity expectations.
 *
 * Coverage contract (enforced by `authorization-legacy-matrix.test.ts`):
 *
 * - RouteId-keyed reconciliation: every frozen route-baseline entry with
 *   `authorizationKind === 'scope'` and a legacy PathRule grant
 *   (`noRuleGrant === false`, 286 entries) is reconciled as
 *   routeId × granting role × applicable operation (GET→read,
 *   POST/PUT/PATCH/DELETE→write, methodless `*`→both) × brand
 *   (brand-1 `/default/...`, brand-2 `/second/...`). Every parity row carries
 *   an explicit `routeId` naming the frozen route it witnesses; for each key
 *   the matrix must contain a same-routeId, same-brand, same-operation row
 *   whose principal resolves the granting role (bootstrap-system-admin counts
 *   as Admin, anonymous counts as Guest for both brands) and whose path
 *   instantiates the named route's own pattern. Shared legacy-rule overlap
 *   alone never witnesses a route. No gate receives a blanket exemption
 *   from path instantiation: `record-acl`, `brand-isolation`,
 *   `bearer-parity`, `guest-baseline`, and `legacy-error` rows also carry
 *   exact route-pattern witnesses (layering is stated in reasons, not in
 *   mismatched paths). Missing keys fail the test.
 * - Explicitly excluded from routeId reconciliation (frozen in
 *   `LEGACY_MATRIX_ROUTE_EXCLUSIONS`, 31 entries): public routes with no rule
 *   grant, pre-auth infrastructure routes, and scope routes with no legacy
 *   rule grant (historically allowed, denied in enforce under security
 *   difference `enforce-no-rule-deny`). Stale exclusions and unexcluded
 *   out-of-scope entries fail the test.
 * - Every distinct legacy rule path template (61 in the frozen baseline) has
 *   at least one brand-1 (`/default/rdmp/...`) row AND at least one brand-2
 *   (`/second/rdmp/...`) row; every template has both a read and a write row
 *   in EACH brand. Per-brand completeness is enforced, not family spot checks.
 * - Both brands (`/default/rdmp/...` and `/second/rdmp/...`) are exercised,
 *   including cross-brand isolation denies.
 * - Every inventoried legacy role, every listed principal, and both
 *   operations appear. Local, AAF, OIDC, linked-account, and legacy bearer
 *   principal shapes are represented through role-equivalent rows.
 * - Read-only grants (can_read without can_update) carry explicit write-deny
 *   rows so the distinction is pinned.
 * - Record ACL, search/Solr, export, attachment, related-record, and
 *   deleted-record families are covered at the PathRule prerequisite layer:
 *   each row pins the legacy path-rule component, while the record/entity ACL
 *   composition is owned by `resource-access.test.ts` and the Phase 7
 *   suites. Reasons state this layering explicitly.
 * - Bearer/disabled/revoked error behavior that differs from legacy history
 *   is NOT duplicated here; it lives in the security-differences fixtures.
 *   The `legacy-error` gate below covers only legacy-denied parity cases
 *   (no grant, unknown role, anonymous on protected paths).
 */

export interface LegacyMatrixBrandFixture {
  readonly brandId: string;
  readonly brandName: string;
  readonly portal: string;
}

export interface LegacyMatrixRoleFixture {
  readonly key: string;
  readonly brandId: string | null;
  readonly protectedKind: 'none' | 'guest' | 'brand-admin' | 'system-admin';
}

export type LegacyMatrixGate =
  | 'path-rule'
  | 'record-acl'
  | 'brand-isolation'
  | 'bearer-parity'
  | 'guest-baseline'
  | 'legacy-error';

export interface LegacyMatrixExpectation {
  readonly principal: string;
  readonly routeId: string;
  readonly brandId: string;
  readonly path: string;
  readonly operation: 'read' | 'write';
  readonly expected: 'allow' | 'deny';
  readonly reason: string;
  readonly gate: LegacyMatrixGate;
}

export interface LegacyMatrixRouteExclusion {
  readonly routeId: string;
  readonly reason: string;
}

